:root {
  --clr-bg: #e8e0d0;
  --clr-border: #8b7355;
  --clr-header-bg: #5a4a32;
  --clr-header-text: #f5ead8;
  --clr-title: #3b2e1a;
  --clr-subtitle: #7a6445;
  --clr-badge-bg: #4a7c59;
  --clr-badge-text: #e8f5ec;
  --clr-label: #9b856a;
  --clr-value: #3b2e1a;
  --clr-detail-bg: #f0e8d8;
  --clr-detail-border: #c8b89a;
  --clr-chip-bg: #c8b89a;
  --clr-chip-text: #3b2e1a;
  --clr-footer-bg: #d4c9b0;
  --clr-date: #7a6445;
}

.workshop-tag {
  width: 420px;
  background-color: var(--clr-bg);
  border: 2px solid var(--clr-border);
  border-radius: 6px;
  overflow: hidden;
  font-size: 13px;
  margin: 0 auto;
}

.tag-header {
  background-color: var(--clr-header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
}

.tag-label {
  color: var(--clr-header-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.tag-number {
  color: var(--clr-header-text);
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0.08em;
  opacity: 0.75;
}

.tag-body {
  padding: 14px 16px 10px;
}

.tag-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 2px;
}

.tag-title {
  font-size: 22px;
  font-weight: 700;
  color: var(--clr-title);
  margin: 0;
  line-height: 1.1;
}

.tag-badge {
  background-color: var(--clr-badge-bg);
  color: var(--clr-badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  padding: 3px 8px;
  border-radius: 3px;
  text-transform: uppercase;
}

.tag-subtitle {
  color: var(--clr-subtitle);
  font-size: 12px;
  font-weight: 400;
  margin: 0 0 12px;
  letter-spacing: 0.04em;
}

.tag-details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.detail-item {
  background-color: var(--clr-detail-bg);
  border: 1px solid var(--clr-detail-border);
  border-radius: 4px;
  padding: 6px 10px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.detail-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--clr-label);
}

.detail-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--clr-value);
}

.tag-footer {
  background-color: var(--clr-footer-bg);
  border-top: 1px solid var(--clr-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
}

.tag-tools {
  display: flex;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.tool-chip {
  background-color: var(--clr-chip-bg);
  color: var(--clr-chip-text);
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 12px;
  letter-spacing: 0.04em;
}

.tag-date {
  color: var(--clr-date);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.06em;
}
